-- See https://wiki.hyprland.org/Configuring/Window-Rules/ for more
-- See https://wiki.hyprland.org/Configuring/Workspace-Rules/ for workspace rules

-- Example windowrule
-- windowrule = float,class:^(kitty)$,title:^(kitty)$

-- Ignore maximize requests from apps. You'll probably like this.
hl.window_rule({
    name  = "suppress_event_maxim",
    match = {
        class = ".*",
    },
    suppress_event = "maximize",
})

-- Fix some dragging issues with XWayland
hl.window_rule({
    name  = "no_focus_on",
    match = {
        class = "^$",
        title = "^$",
        xwayland = 1,
        float = 1,
        fullscreen = 0,
        pin = 0,
    },
    no_focus = true,
})

-- https://github.com/hyprwm/Hyprland/issues/4117
-- https://wiki.hypr.land/0.53.0/Configuring/Window-Rules/

hl.window_rule({
    name  = "match_fullscreen_on",
    match = {
        fullscreen = true,
    },
    border_size = 0,
    rounding = 0,
})

--################
--## AUTOSTART ###
--################

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
-- exec-once = $terminal
-- exec-once = waybar & hyprpaper & firefox

hl.on("hyprland.start", function()
    hl.exec_cmd("nm-applet")
    hl.exec_cmd("waybar")
    -- https://wiki.hypr.land/FAQ#how-do-i-change-me-mouse-cursor
    hl.exec_cmd("hyprctl setcursor Adwaita 24")
    hl.exec_cmd("hypridle")
end)
